```python
import time
import requests


class RateLimitError(Exception):
    pass


class APIError(Exception):
    def __init__(self, status_code, message):
        super().__init__(message)
        self.status_code = status_code


class AIClient:
    def __init__(self, api_key, base_url="https://api.anthropic.com"):
        self.api_key = api_key
        self.base_url = base_url
        self.session = requests.Session()
        self.session.headers.update({
            "x-api-key": api_key,
            "anthropic-version": "2023-06-01",
        })

    def send_message(self, model, messages, max_tokens=1024):
        for attempt in range(3):
            resp = self.session.post(
                f"{self.base_url}/v1/messages",
                json={"model": model, "messages": messages, "max_tokens": max_tokens},
            )
            if resp.status_code == 429 or resp.status_code >= 500:
                if attempt < 2:
                    wait = int(resp.headers.get("retry-after", 2 ** attempt))
                    time.sleep(wait)
                    continue
                raise RateLimitError("Retries exhausted")
            if resp.status_code >= 400:
                raise APIError(resp.status_code, resp.json().get("error", {}).get("message", "Unknown error"))
            return resp.json()

    def list_models(self):
        resp = self.session.get(f"{self.base_url}/v1/models")
        resp.raise_for_status()
        return resp.json()
```

