from unittest.mock import patch, MagicMock


def test_retries_on_rate_limit():
    client = AIClient(api_key="test-key")
    rate_limited = MagicMock(status_code=429, headers={})
    success = MagicMock(status_code=200)
    success.json.return_value = {"content": [{"text": "ok"}]}

    with patch.object(client.session, "post", side_effect=[rate_limited, success]):
        with patch("time.sleep"):
            result = client.send_message("claude-sonnet-5", [{"role": "user", "content": "hi"}])

    assert result["content"][0]["text"] == "ok"


def test_raises_after_exhausting_retries():
    client = AIClient(api_key="test-key")
    rate_limited = MagicMock(status_code=429, headers={})

    with patch.object(client.session, "post", side_effect=[rate_limited, rate_limited, rate_limited]):
        with patch("time.sleep"):
            try:
                client.send_message("claude-sonnet-5", [{"role": "user", "content": "hi"}])
                assert False, "expected RateLimitError"
            except RateLimitError:
                pass
```

