import hmac
import hashlib
import time

PROCESSED_EVENT_IDS = set()  # a real implementation uses a database table


def verify_signature(raw_body: bytes, signature_header: str, secret: str) -> bool:
    parts = dict(p.split("=") for p in signature_header.split(","))
    timestamp, signature = parts["t"], parts["v1"]
    signed_payload = f"{timestamp}.{raw_body.decode()}"
    expected = hmac.new(secret.encode(), signed_payload.encode(), hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected, signature)


def handle_webhook(raw_body: bytes, signature_header: str, secret: str) -> int:
    if not verify_signature(raw_body, signature_header, secret):
        return 401  # reject before trusting anything in the payload

    import json
    event = json.loads(raw_body)

    if event["id"] in PROCESSED_EVENT_IDS:
        return 200  # already handled this exact event — safe no-op

    if event["type"] == "batch.completed":
        queue_batch_processing(event["data"]["object"])  # real work, queued
        PROCESSED_EVENT_IDS.add(event["id"])

    return 200  # respond fast, regardless of how long queue_batch_processing takes


def backfill_missed_batches(client) -> None:
    """Run on a schedule. Catches any batch that completed without a
    webhook delivery ever arriving."""
    cursor = None
    while True:
        page = client.list_batches(starting_after=cursor)
        for batch in page["data"]:
            if batch["status"] == "completed" and batch["id"] not in PROCESSED_EVENT_IDS:
                queue_batch_processing(batch)
                PROCESSED_EVENT_IDS.add(batch["id"])
        if not page["has_more"]:
            break
        cursor = page["data"][-1]["id"]


